class AlumnoCFP:
    def __init__(self, nombre, legajo):
        self.nombre = nombre
        self.legajo = legajo
        self.notas = []
        self.estado = "Cursando"

    def registrar_nota(self, calificacion):
        if 1 <= calificacion <= 10:
            self.notas.append(calificacion)
            print(f"[OK] Nota {calificacion} cargada para {self.nombre}")
        else:
            print(f"[ERROR] La calificación {calificacion} es inválida (debe ser entre 1 y 10)")

    def calcular_promedio(self):
        if not self.notas:
            return 0.0
        return sum(self.notas) / len(self.notas)

    def verificar_aprobacion(self):
        prom = self.calcular_promedio()
        if prom >= 7.0:
            self.estado = "Promocionado"
        elif prom >= 4.0:
            self.estado = "Aprobado (Final)"
        else:
            self.estado = "Desaprobado"
        return self.estado

